import { builtLocales, liveLocales, type LocaleId } from './locales';

/**
 * Versions generated by this build. Production: only the live ones (today « en », served at « / »).
 * The private preview environment also builds the « preview » versions (see ./locales.ts).
 * D42 (English only) was cancelled by the owner on 17/11/2026: international versions are added
 * progressively, one country at a time.
 */
export const LOCALES = builtLocales() as [LocaleId, ...LocaleId[]];
/** Versions open to the public (indexable, orders open) — decided on the server, never by the browser. */
export const LIVE_LOCALES = liveLocales() as [LocaleId, ...LocaleId[]];
export type Locale = LocaleId;
export const DEFAULT_LOCALE: Locale = 'en';

export function isLocale(value: unknown): value is Locale {
  return typeof value === 'string' && (LOCALES as readonly string[]).includes(value);
}
